<?php
namespace SenderSuite;

/** Encrypted active auth/scheduling settings. Runtime secrets use separately purpose-bound vault methods; other source environment settings remain metadata. */
final class Config {
    private $vault;private $read;private $write;private $values;
    private const DEFAULTS=array('APP_NAME'=>'Sendify','APP_ENV'=>'production','ADMIN_USERNAME'=>'admin','ADMIN_PASSWORD'=>null,'LOGIN_PASSWORD'=>null,'SECRET_KEY'=>null,'ACCESS_TOKEN_EXPIRE_MINUTES'=>1440,'RATE_LIMIT_LOGIN'=>'10/minute','DEFAULT_TIMEZONE'=>'Africa/Lagos');
    public function __construct(Vault $vault,callable $read,callable $write) { $this->vault=$vault;$this->read=$read;$this->write=$write; }
    public static function database(Database $db,$prefix,Vault $vault) { $table=Schema::identifier($prefix.'sender_suite_config');return new self($vault,function()use($db,$table){$out=array();foreach ($db->rows('SELECT name,payload FROM '.$table) as $row) {$out[$row['name']]=$row['payload'];}return $out;},function($values)use($db,$table){$db->transaction(function()use($db,$table,$values){foreach($values as $name=>$payload){$db->execute('INSERT INTO '.$table.' (name,payload,updated_at) VALUES (%s,%s,UTC_TIMESTAMP(6)) ON DUPLICATE KEY UPDATE payload=VALUES(payload),updated_at=VALUES(updated_at)',array($name,$payload));}});}); }
    private function load() { if ($this->values!==null) {return;} $values=self::DEFAULTS;foreach (($this->read)() as $name=>$encrypted) {if (!array_key_exists($name,self::DEFAULTS)){continue;}$values[$name]=json_decode($this->vault->open('config/'.$name,$encrypted),true,512,JSON_THROW_ON_ERROR);} $this->validate($values);$this->values=$values; }
    private function validate(array $data) { foreach($data as $name=>$value){if(!array_key_exists($name,self::DEFAULTS)){throw new \InvalidArgumentException('Unknown active setting.');}if($name==='ACCESS_TOKEN_EXPIRE_MINUTES'){if(!is_int($value)||$value<1||$value>525600){throw new \InvalidArgumentException('Invalid session lifetime.');}}elseif($value!==null&&!is_string($value)){throw new \InvalidArgumentException('Settings require text.');}}if(!is_string($data['DEFAULT_TIMEZONE'])||!in_array($data['DEFAULT_TIMEZONE'],\DateTimeZone::listIdentifiers(\DateTimeZone::ALL_WITH_BC),true)){throw new \InvalidArgumentException('Invalid application timezone.');}if(!in_array($data['APP_ENV'],array('development','production'),true)){throw new \InvalidArgumentException('Invalid application environment.');}if(!preg_match('/^[1-9][0-9]*\/(second|minute|hour|day)s?$/D',$data['RATE_LIMIT_LOGIN'])){throw new \InvalidArgumentException('Invalid login limit.');} }
    public function get($name) { if(!array_key_exists($name,self::DEFAULTS)){throw new \InvalidArgumentException('Unknown active setting.');}$this->load();return $this->values[$name]; }
    public function ready() {return is_string($this->get('SECRET_KEY'))&&strlen($this->get('SECRET_KEY'))>=32&&Compat::strip($this->get('ADMIN_PASSWORD')??'')!=='';}
    public function save(array $updates) { $this->load();$data=array_merge($this->values,$updates);$this->validate($data);$encrypted=array();foreach($data as $name=>$value){$encrypted[$name]=$this->vault->seal('config/'.$name,json_encode($value,JSON_THROW_ON_ERROR));}($this->write)($encrypted);$this->values=$data; }
    public function setup($username,$password) { $username=Compat::strip($username);if($username===''||Compat::length($username)>150||!is_string($password)||Compat::strip($password)===''){throw new \InvalidArgumentException('Enter an operator username and a nonblank password.');}$updates=array('ADMIN_USERNAME'=>$username,'ADMIN_PASSWORD'=>$password);if(!$this->get('SECRET_KEY')){$updates['SECRET_KEY']=bin2hex(random_bytes(32));}$this->save($updates); }
    /** Internal, row/purpose-bound secret protection. Never exposed as an arbitrary REST encrypt/decrypt API. */
    public function sealRuntimeSecret($field,$plaintext) { return $this->vault->seal('runtime/'.$field,$plaintext); }
    public function openRuntimeSecret($field,$envelope) { return $this->vault->open('runtime/'.$field,$envelope); }
    public function __debugInfo(){return array('configuration'=>'[redacted]');}public function __serialize(){throw new \RuntimeException('Configuration serialization forbidden.');}public function __sleep(){throw new \RuntimeException('Configuration serialization forbidden.');}
}
